EDITS = {'components/shell/Sidebar.tsx': [('IconeVendasGerais', "import { useTrocasBadge } from '@/lib/vendas/useTrocasBadge'\n", "import { useTrocasBadge } from '@/lib/vendas/useTrocasBadge'\nimport { Table2 as IconeVendasGerais } from 'lucide-react'\n", 'Sidebar: ícone de Vendas Gerais'), ("href: '/admin/vendas/gerais'", "          { label: 'Vendas Individuais', icon: Users, href: '/admin/vendas' },\n", "          { label: 'Vendas Gerais', icon: IconeVendasGerais, href: '/admin/vendas/gerais' },\n          { label: 'Vendas Individuais', icon: Users, href: '/admin/vendas' },\n", 'Sidebar: "Vendas Gerais" como PRIMEIRA opção da seção Vendas')], 'components/shell/MobileDrawer.tsx': [('IconeVendasGerais', "import { useTrocasBadge } from '@/lib/vendas/useTrocasBadge'\n", "import { useTrocasBadge } from '@/lib/vendas/useTrocasBadge'\nimport { Table2 as IconeVendasGerais } from 'lucide-react'\n", 'Menu do celular: ícone de Vendas Gerais'), ("href: '/admin/vendas/gerais'", "  { key: 'vendas-admin',  label: 'Vendas Individuais', icon: Receipt, href: '/admin/vendas',     always: true, adminOnly: true },\n", "  { key: 'vendas-gerais', label: 'Vendas Gerais', icon: IconeVendasGerais, href: '/admin/vendas/gerais', always: true, adminOnly: true },\n  { key: 'vendas-admin',  label: 'Vendas Individuais', icon: Receipt, href: '/admin/vendas',     always: true, adminOnly: true },\n", 'Menu do celular: "Vendas Gerais" antes de Vendas Individuais')], 'components/vendas/VendasTable.tsx': [("from '@/lib/vendas/ordem'", "import { Chip } from './ui'\n", "import { Chip } from './ui'\nimport { ordenarVendas, type Ordem } from '@/lib/vendas/ordem'\n", 'Tabela: import da ordenação'), ("ordem = 'recentes'", "export function VendasTable({ rows, mode, onSaveObs, onEdit, pageSize = 25, empty = 'Nenhuma venda neste período.' }: { rows: VendaRow[]; mode: 'closer' | 'admin'; onSaveObs: SaveObs; onEdit?: (row: VendaRow) => void; pageSize?: number; empty?: string }) {\n", "export function VendasTable({ rows, mode, onSaveObs, onEdit, pageSize = 25, ordem = 'recentes', empty = 'Nenhuma venda neste período.' }: { rows: VendaRow[]; mode: 'closer' | 'admin'; onSaveObs: SaveObs; onEdit?: (row: VendaRow) => void; pageSize?: number; ordem?: Ordem; empty?: string }) {\n", 'Tabela: aceita a ordem'), ('ordenarVendas(rows, ordem)', '  const slice = useMemo(() => rows.slice(page * pageSize, page * pageSize + pageSize), [rows, page, pageSize])\n', '  const ordenadas = useMemo(() => ordenarVendas(rows, ordem), [rows, ordem])      // a ordem escolhida (padrão: mais recentes primeiro)\n  useEffect(() => { setPage(0) }, [ordem])\n  const slice = useMemo(() => ordenadas.slice(page * pageSize, page * pageSize + pageSize), [ordenadas, page, pageSize])\n', 'Tabela: ordena antes de paginar (e volta à página 1 ao mudar a ordem)')], 'app/(platform)/admin/vendas/VendasIndividuaisClient.tsx': [("from '@/lib/vendas/ordem'", "import { PeriodoFilter } from '@/components/vendas/PeriodoFilter'\n", "import { PeriodoFilter } from '@/components/vendas/PeriodoFilter'\nimport { ArrowDownUp } from 'lucide-react'\nimport { ORDENS, ordemValida } from '@/lib/vendas/ordem'\n", 'Vendas Individuais: imports do filtro de ordem'), ('setOrdem] = useState', 'export function VendasIndividuaisClient() {\n', "export function VendasIndividuaisClient() {\n  const [ordem, setOrdem] = useState('recentes')\n", 'Vendas Individuais: estado da ordem'), ("inativos || ordem !== 'recentes'", '|| !recorrentes || inativos\n', "|| !recorrentes || inativos || ordem !== 'recentes'\n", 'Vendas Individuais: ordem diferente do padrão liga o "Limpar filtros"'), ("setOrdem('recentes') }", 'setRecorrentes(true); setInativos(false) }\n', "setRecorrentes(true); setInativos(false); setOrdem('recentes') }\n", 'Vendas Individuais: "Limpar filtros" volta a ordem ao padrão'), ('name="ordem"', '        <Switch dataV="filtro-recorrentes" checked={recorrentes} onChange={setRecorrentes} label="Parcelas recorrentes" />\n', '        <Select name="ordem" caption="Ordenar por" icon={<ArrowDownUp size={18} />} value={ordem} onChange={setOrdem} defaultValue="recentes" options={ORDENS.map(o => ({ value: o.value, label: o.label }))} />\n        <Switch dataV="filtro-recorrentes" checked={recorrentes} onChange={setRecorrentes} label="Parcelas recorrentes" />\n', 'Vendas Individuais: filtro "Ordenar por"'), ('ordem={ordemValida(ordem)}', '<VendasTable rows={b.rows} mode="admin" ', '<VendasTable rows={b.rows} mode="admin" ordem={ordemValida(ordem)} ', 'Vendas Individuais: a tabela de cada closer usa a ordem')], 'app/(platform)/vendas/MinhasVendasClient.tsx': [("from '@/lib/vendas/ordem'", "import { PeriodoFilter } from '@/components/vendas/PeriodoFilter'\n", "import { PeriodoFilter } from '@/components/vendas/PeriodoFilter'\nimport { ArrowDownUp } from 'lucide-react'\nimport { ORDENS, ordemValida } from '@/lib/vendas/ordem'\n", 'Minhas Vendas: imports do filtro de ordem'), ('setOrdem] = useState', 'export function MinhasVendasClient({ team }: { team: string | null }) {\n', "export function MinhasVendasClient({ team }: { team: string | null }) {\n  const [ordem, setOrdem] = useState('recentes')\n", 'Minhas Vendas: estado da ordem'), ("!!busca || ordem !== 'recentes'", '|| !recorrentes || !!busca\n', "|| !recorrentes || !!busca || ordem !== 'recentes'\n", 'Minhas Vendas: ordem diferente do padrão liga o "Limpar filtros"'), ("setOrdem('recentes') }", "setRecorrentes(true); setBusca('') }\n", "setRecorrentes(true); setBusca(''); setOrdem('recentes') }\n", 'Minhas Vendas: "Limpar filtros" volta a ordem ao padrão'), ('name="ordem"', '        <Switch dataV="filtro-recorrentes" checked={recorrentes} onChange={setRecorrentes} label="Parcelas recorrentes" />\n', '        <Select name="ordem" caption="Ordenar por" icon={<ArrowDownUp size={18} />} value={ordem} onChange={setOrdem} defaultValue="recentes" options={ORDENS.map(o => ({ value: o.value, label: o.label }))} />\n        <Switch dataV="filtro-recorrentes" checked={recorrentes} onChange={setRecorrentes} label="Parcelas recorrentes" />\n', 'Minhas Vendas: filtro "Ordenar por"'), ('ordem={ordemValida(ordem)}', '<VendasTable rows={filtradas} mode="closer" ', '<VendasTable rows={filtradas} mode="closer" ordem={ordemValida(ordem)} ', 'Minhas Vendas: a tabela usa a ordem')]}
