def txt(b64): return base64.b64decode(b64).decode('utf-8')
def le(rel):
    raw = open(P(rel), 'rb').read(); bom = raw.startswith(b'\xef\xbb\xbf'); t = (raw[3:] if bom else raw).decode('utf-8')
    return t.replace('\r\n', '\n'), ('\r\n' in t), bom
def grava(rel, t, crlf, bom):
    b = (t.replace('\n', '\r\n') if crlf else t).encode('utf-8'); open(P(rel), 'wb').write((b'\xef\xbb\xbf' + b) if bom else b)
if not os.path.isdir(P('app')) or not os.path.isdir(P('components')) or not os.path.isdir(P('lib')): print(__doc__); sys.exit(2)

if UNDO:
    feitos = []
    for rel in EDITS:
        if os.path.isfile(P(rel) + BAK): os.replace(P(rel) + BAK, P(rel)); feitos.append('restaurado ' + rel)
    for rel, (h, b64) in NOVOS.items():
        if os.path.exists(P(rel)):
            if le(rel)[0] == txt(b64):
                if not DRY: os.remove(P(rel)); feitos.append('apagado ' + rel)
            else: print(f'  ! {rel} foi alterado por você: NÃO apaguei')
    for d in ('app/(platform)/admin/vendas/gerais', 'app/api/admin/vendas/gerais/resumo', 'app/api/admin/vendas/gerais'):
        try: os.rmdir(P(d))
        except OSError: pass
    print('Desfeito:\n  ' + '\n  '.join(feitos) if feitos else 'Nada a desfazer.'); sys.exit(0)

print({True: 'SIMULAÇÃO (nada será gravado)', False: 'APLICANDO'}[DRY], '— Vendas Gerais + filtro de ordem\n')
falhas, plano_edit, plano_novos, msgs = 0, [], [], []
for rel in ['lib/vendas/handlers.ts', 'lib/vendas/format.ts', 'components/vendas/ui.tsx', 'lib/vendas/client.ts']:
    if not os.path.isfile(P(rel)): print(f'✘ falta {rel}: o pacote de Vendas não está instalado neste projeto.'); falhas += 1
for rel, (h, b64) in NOVOS.items():
    if hashlib.sha256(txt(b64).encode('utf-8')).hexdigest() != h: print(f'✘ este script está corrompido ({rel}): baixe de novo.'); falhas += 1
if falhas: print('\nNADA foi gravado.'); sys.exit(1)
ref_crlf = False
for rel in ('components/vendas/VendasTable.tsx', 'components/shell/Sidebar.tsx'):
    if os.path.isfile(P(rel)): ref_crlf = le(rel)[1]; break
print('Arquivos NOVOS')
for rel, (h, b64) in NOVOS.items():
    if not os.path.exists(P(rel)): plano_novos.append(rel); print('  + criar  ' + rel)
    elif le(rel)[0] == txt(b64): print('  · já existe igual: ' + rel)
    else: print(f'  ✗ já existe e é DIFERENTE (não vou sobrescrever): {rel}'); falhas += 1
for rel, edits in EDITS.items():
    print('\nEditar ' + rel)
    if not os.path.isfile(P(rel)): print('  ✗ arquivo não encontrado'); falhas += 1; continue
    t, crlf, bom = le(rel); novo = t; ok = True
    for marcador, antes, depois, desc in edits:
        if marcador in novo: print('  · já estava: ' + desc); continue
        n = novo.count(antes)
        if n != 1: print(f'  ✗ {desc}: o trecho esperado apareceu {n} vez(es) (precisa ser exatamente 1)'); ok = False; continue
        novo = novo.replace(antes, depois); print('  ✓ ' + desc)
    if not ok: falhas += 1
    elif novo != t: plano_edit.append((rel, novo, crlf, bom))
if falhas: print(f'\nNADA foi gravado ({falhas} problema(s)). Me mande o arquivo indicado que eu ajusto o script.'); sys.exit(1)
if not plano_novos and not plano_edit: print('\nJá aplicado. Nada foi alterado.'); sys.exit(0)
if DRY: print('\n(simulação) nada foi gravado.'); sys.exit(0)
for rel, novo, crlf, bom in plano_edit:
    if not os.path.exists(P(rel) + BAK): open(P(rel) + BAK, 'wb').write(open(P(rel), 'rb').read())
    grava(rel, novo, crlf, bom)
for rel in plano_novos:
    os.makedirs(os.path.dirname(P(rel)), exist_ok=True); grava(rel, txt(NOVOS[rel][1]), ref_crlf, False)
print("""
OK: Vendas Gerais instalada.
  • Superadmin: Vendas → "Vendas Gerais" (primeira opção) abre /admin/vendas/gerais.
  • "Ordenar por" (mais recentes · mais antigas · maior valor · menor valor) agora também em Vendas Individuais e em Minhas Vendas.
Próximo passo: git add -A · git commit · git push · deploy. Não precisa de migração nem de variável nova.""")
